// Generated by Cypress Author on 2026-10-19 (INV 04) e 2026-10-22 (INV 03, INV 05)
//
// INV 04 (P0) · INV 03 · INV 05 — Plano_de_Testes_QA_MatchWallet.md §10.
// Abrir a composição de outra carteira é só consulta: nenhuma mutação sai do navegador e o
// vínculo do cliente (GET /auth/me) não muda.

const base = { descricao: 'Descrição', ativa: true, criadoEm: '2026-01-01T00:00:00.000Z' }

const MODERADA = {
  ...base,
  id: 'cart-mod',
  nome: 'Carteira Moderada',
  perfilAlvo: 'MODERADO',
  versaoAtual: {
    id: 'v1',
    mesReferencia: '2026-10',
    publicada: true,
    publicadaEm: '2026-10-01T00:00:00.000Z',
    itens: [
      {
        id: 'i1',
        ativoId: 'a1',
        tickerCodigo: 'ITUB4',
        nomeAtivo: 'Itaú Unibanco',
        classeAtivo: 'Ações',
        pesoPercentual: 100,
        statusMovimentacao: 'MANTER',
      },
    ],
  },
}

const ARROJADA = {
  ...base,
  id: 'cart-arr',
  nome: 'Carteira Arrojada',
  perfilAlvo: 'ARROJADO',
  versaoAtual: null,
}

const CLIENTE_SEM_VINCULO = {
  id: '11111111-1111-4111-8111-111111111111',
  nome: 'Maria Teste',
  email: 'maria@teste.com',
  perfil: 'cliente',
  perfilInvestidor: null,
  carteiraVinculada: null,
}

const CONSERVADORA = {
  ...base,
  id: 'cart-cons',
  nome: 'Carteira Conservadora',
  descricao: 'Foco em preservação de capital',
  perfilAlvo: 'CONSERVADOR',
  versaoAtual: {
    id: 'v-cons',
    mesReferencia: '2026-10',
    publicada: true,
    publicadaEm: '2026-10-01T00:00:00.000Z',
    itens: [
      {
        id: 'c1',
        ativoId: 'ac1',
        tickerCodigo: 'TESO',
        nomeAtivo: 'Tesouro Selic',
        classeAtivo: 'Renda fixa',
        pesoPercentual: 100,
        statusMovimentacao: 'MANTER',
      },
    ],
  },
}

const MODERADA_DIVIDENDOS = {
  ...MODERADA,
  id: 'cart-mod-2',
  nome: 'Moderada Dividendos',
  descricao: null,
}

function stubCatalogo(carteiras: Array<{ id: string }>) {
  cy.bloquearApi()
  cy.intercept('GET', '**/api/v1/auth/me', CLIENTE_SEM_VINCULO).as('me')
  cy.stubApi(
    'GET',
    '/carteiras*',
    { items: carteiras, total: carteiras.length, page: 1, pageSize: 100 },
    'listar',
  )
  for (const carteira of carteiras) {
    cy.stubApi('GET', `/carteiras/${carteira.id}`, carteira, `detalhe-${carteira.id}`)
  }
  // Rascunhos vêm de /versoes (admin): o catálogo nunca deve chamar.
  cy.intercept('GET', '**/api/v1/carteiras/*/versoes*', { statusCode: 200, body: {} }).as('versoes')
}

function cartao(nome: string) {
  return cy.contains('[data-slot="wallet-card"]', nome)
}

describe('Plano QA · Catálogo de carteiras', () => {
  it('INV 04 · cliente vinculado abre a composição de outra carteira → só lê, sem mutação e sem mudar o vínculo', () => {
    cy.bloquearApi()
    // Cliente vinculado à Moderada.
    cy.intercept('GET', '**/api/v1/auth/me', {
      id: '11111111-1111-4111-8111-111111111111',
      nome: 'Maria Teste',
      email: 'maria@teste.com',
      perfil: 'cliente',
      perfilInvestidor: 'MODERADO',
      carteiraVinculada: { id: MODERADA.id, nome: MODERADA.nome, perfilAlvo: 'MODERADO' },
    }).as('me')
    cy.stubApi(
      'GET',
      '/carteiras*',
      { items: [MODERADA, ARROJADA], total: 2, page: 1, pageSize: 100 },
      'listar',
    )
    cy.stubApi('GET', `/carteiras/${MODERADA.id}`, MODERADA, 'detalheMod')
    cy.stubApi('GET', `/carteiras/${ARROJADA.id}`, ARROJADA, 'detalheArr')
    // Qualquer escrita, em qualquer rota, entra aqui (declarada por último = prioridade).
    cy.intercept({ method: /POST|PUT|PATCH|DELETE/, url: '**/api/v1/**' }, (req) => {
      req.reply({ statusCode: 200, body: {} })
    }).as('mutacao')

    cy.visit('/carteiras')
    cy.wait(['@detalheMod', '@detalheArr'])

    cy.contains('[data-slot="wallet-card"]', 'Carteira Arrojada')
      .contains('button', 'Ver composição')
      .click()
    cy.contains('Esta carteira ainda não tem uma versão publicada.').should('be.visible')
    cy.contains('Esta não é a carteira recomendada para o seu perfil').should(
      'contain.text',
      'Carteira Moderada',
    )

    cy.get('[aria-label="Fechar composição"]').click()
    cy.contains('Esta carteira ainda não tem uma versão publicada.').should('not.exist')

    // Consulta não gerou escrita nem recarregou a sessão (vínculo intacto).
    cy.get('@mutacao.all').should('have.length', 0)
    cy.get('@me.all').should('have.length', 1)
    cy.contains('[data-slot="wallet-card"]', 'Carteira Moderada').should(
      'contain.text',
      'sua carteira',
    )
  })

  it('INV 03 · seleciona cada perfil e "TODOS OS PERFIS" → lista compatível, filtro marcado e cartões com os dados certos', () => {
    stubCatalogo([CONSERVADORA, MODERADA, MODERADA_DIVIDENDOS, ARROJADA])

    cy.visit('/carteiras')
    cy.get('[data-slot="wallet-card"]').should('have.length', 4)

    const filtro = (nome: string) =>
      cy.contains('[aria-label="Filtrar carteiras por perfil"] button', nome)

    // Um botão por perfil existente (MODERADO aparece uma vez, mesmo com 2 carteiras) + todos.
    cy.get('[aria-label="Filtrar carteiras por perfil"] button').should('have.length', 4)
    filtro('TODOS OS PERFIS').should('have.attr', 'aria-pressed', 'true')

    // Cartões trazem nome, perfil, descrição e contagem de ativos corretos.
    cartao('Carteira Conservadora')
      .should('contain.text', 'CONSERVADOR')
      .and('contain.text', 'Foco em preservação de capital')
      .and('contain.text', '1 ativo')
    cartao('Carteira Moderada').should('contain.text', 'MODERADO').and('contain.text', '1 ativo')
    cartao('Moderada Dividendos').should('contain.text', 'Sem descrição cadastrada.')
    cartao('Carteira Arrojada').should('contain.text', 'ARROJADO').and('contain.text', '0 ativos')

    // Cada filtro mostra só o seu perfil e marca apenas o botão ativo.
    filtro('MODERADO').click()
    filtro('MODERADO').should('have.attr', 'aria-pressed', 'true')
    filtro('TODOS OS PERFIS').should('have.attr', 'aria-pressed', 'false')
    cy.get('[data-slot="wallet-card"]').should('have.length', 2)
    cy.get('[data-slot="wallet-card"]').each(($card) => {
      expect($card.text()).to.contain('MODERADO')
    })

    filtro('CONSERVADOR').click()
    cy.get('[data-slot="wallet-card"]').should('have.length', 1)
    cartao('Carteira Conservadora').should('be.visible')

    filtro('ARROJADO').click()
    cy.get('[data-slot="wallet-card"]').should('have.length', 1)
    cartao('Carteira Arrojada').should('be.visible')

    filtro('TODOS OS PERFIS').click()
    filtro('TODOS OS PERFIS').should('have.attr', 'aria-pressed', 'true')
    cy.get('[data-slot="wallet-card"]').should('have.length', 4)

    // Perfil sem carteira (SOFISTICADO) não tem filtro: ausência não é, por si só, defeito.
    cy.contains('[aria-label="Filtrar carteiras por perfil"] button', 'SOFISTICADO').should(
      'not.exist',
    )
  })

  it('INV 05 · abre carteira publicada e carteira sem versão → composição, aviso legal e link corretos, nada de rascunho, foco volta ao cartão', () => {
    stubCatalogo([MODERADA, ARROJADA])

    cy.visit('/carteiras')
    cy.wait(['@detalhe-cart-mod', '@detalhe-cart-arr'])

    // Publicada: ativos e pesos, descrição e aviso legal.
    cartao('Carteira Moderada').contains('button', 'Ver composição').click()
    cy.get('[role="dialog"]').within(() => {
      cy.contains('Composição vigente').should('be.visible')
      cy.contains('Composição · 1 ativos').should('be.visible')
      cy.contains('li', 'Itaú Unibanco').should('contain.text', '100,00 %')
      cy.contains('Descrição A composição é revisada mensalmente pela equipe de análise.').should(
        'be.visible',
      )
      cy.contains('Aviso legal').should('be.visible')
      cy.contains('Rentabilidade passada não garante resultados futuros.').should('be.visible')
      cy.contains('a', 'Refazer avaliação de perfil')
        .should('have.attr', 'href', '/avaliacao-perfil')
        .and('be.visible')
    })

    // Fechar devolve o foco ao botão que abriu.
    cy.get('[aria-label="Fechar composição"]').click()
    cy.get('[role="dialog"]').should('not.exist')
    cartao('Carteira Moderada').contains('button', 'Ver composição').should('have.focus')

    // Sem versão: mensagem explícita e nenhuma composição.
    cartao('Carteira Arrojada').contains('button', 'Ver composição').click()
    cy.get('[role="dialog"]').within(() => {
      cy.contains('Esta carteira ainda não tem uma versão publicada.').should('be.visible')
      cy.contains('Composição vigente').should('not.exist')
      cy.contains(/Composição · \d+ ativos/).should('not.exist')
      cy.contains('Aviso legal').should('be.visible')
    })
    cy.get('body').type('{esc}')
    cy.get('[role="dialog"]').should('not.exist')
    cartao('Carteira Arrojada').contains('button', 'Ver composição').should('have.focus')

    // O link do aviso leva à avaliação.
    cartao('Carteira Moderada').contains('button', 'Ver composição').click()
    cy.contains('[role="dialog"] a', 'Refazer avaliação de perfil').click()
    cy.location('pathname').should('eq', '/avaliacao-perfil')

    // Catálogo é leitura pública: nada de rascunhos (rota admin /versoes) nem escrita.
    cy.get('@versoes.all').should('have.length', 0)
  })
})

export {}
